public final class TokenLoginModule implements LoginModule {
    private Subject subject;
    private CallbackHandler callbackHandler;
    private TokenVerifier verifier;
    private Principal principal;
    private boolean succeeded;

    @Override public void initialize(Subject subject, CallbackHandler callbackHandler,
                                     Map<String, ?> sharedState, Map<String, ?> options) {
        this.subject = subject;
        this.callbackHandler = callbackHandler;
        this.verifier = TokenVerifier.from(options);
    }

    @Override public boolean login() throws LoginException {
        String token = readToken(callbackHandler);          // invokes CallbackHandler
        principal = verifier.verify(token);
        if (principal == null)
            throw new FailedLoginException("invalid credentials");
        succeeded = true;
        return true;
    }

    @Override public boolean commit() {
        if (!succeeded) return false;
        subject.getPrincipals().add(principal);
        return true;
    }

    @Override public boolean abort() { clear(); return true; }
    @Override public boolean logout() {
        if (principal != null) subject.getPrincipals().remove(principal);
        clear();
        return true;
    }
    private void clear() { principal = null; succeeded = false; }
}
